(4063404, 581714, 65234, '<td valign="top">My fave so far :-)  Fabulous detail on the bird (look at that eye!!!) and the windblown feathers; like the composition with the curve of the branch, and the background sets it all off nicely, with the added bonus of the cream-colored patch matching the curve of the bird''s cheek.</td>', 'My fave so far :-)  Fabulous detail on the bird (look at that eye!!!) and the windblown feathers; like the composition with the curve of the branch, and the background sets it all off nicely, with the added bonus of the cream-colored patch matching the curve of the bird''s cheek.', '2007-09-05 22:43:42.000000', NULL, 1),
(4063411, 582167, 65234, '<td valign="top">It *is* a lovely branch, with echoes of the shape in the background.  The very bright spots are a little too bright for my taste, but overall a lovely image.</td>', 'It *is* a lovely branch, with echoes of the shape in the background.  The very bright spots are a little too bright for my taste, but overall a lovely image.', '2007-09-05 22:44:54.000000', NULL, 1),
(4063418, 579467, 65234, '<td valign="top">I have no idea what I''m looking at (buttons, maybe?), but that''s often fun ;-)  Whatever they are they seem to be assembling out to infinity in a pleasing pattern.</td>', 'I have no idea what I''m looking at (buttons, maybe?), but that''s often fun ;-)  Whatever they are they seem to be assembling out to infinity in a pleasing pattern.', '2007-09-05 22:46:50.000000', NULL, 1),
(4063420, 581825, 77521, '<td valign="top">woah! what an amazing shot!!! too bad the wings are blurry, but im sure that its almost impossible to avoid that! 9</td>', 'woah! what an amazing shot!!! too bad the wings are blurry, but im sure that its almost impossible to avoid that! 9', '2007-09-05 22:46:58.000000', NULL, 1),
