(4065303, 582483, 81664, '<td valign="top">Very nice bokeh in the background. The main subject looks to be sharpened a little too much, but at the same time, it isn''t quite in focus. Wonderful pink color though!</td>', 'Very nice bokeh in the background. The main subject looks to be sharpened a little too much, but at the same time, it isn''t quite in focus. Wonderful pink color though!', '2007-09-06 13:14:22.000000', NULL, 1),
(4065304, 579607, 81664, '<td valign="top">Nice work on the background bokeh. I find that little leaf showing in the bottom right to be distracting. I do like the extra branch hanging at the top (middlish area)</td>', 'Nice work on the background bokeh. I find that little leaf showing in the bottom right to be distracting. I do like the extra branch hanging at the top (middlish area)', '2007-09-06 13:16:29.000000', NULL, 1),
(4065308, 582249, 81664, '<td valign="top">I just love the background bokeh color, but the "stick" is not very appealing to me. I do like the detail, but it doesn''t seem to match the background.</td>', 'I just love the background bokeh color, but the "stick" is not very appealing to me. I do like the detail, but it doesn''t seem to match the background.', '2007-09-06 13:18:42.000000', NULL, 1),
(4065312, 581631, 81664, '<td valign="top">oh this is a different angle. I like it. I love the other stem in the background. Nice bokeh.</td>', 'oh this is a different angle. I like it. I love the other stem in the background. Nice bokeh.', '2007-09-06 13:20:58.000000', NULL, 1),
(4065313, 581872, 81664, '<td valign="top">I wish the rose was a bit crisper in focus. It is a gorgeous color. Great bokeh in the background - 7!</td>', 'I wish the rose was a bit crisper in focus. It is a gorgeous color. Great bokeh in the background - 7!', '2007-09-06 13:21:49.000000', NULL, 1),
(4065314, 582435, 81664, '<td valign="top">A little too much sun on your subject I think. Too much going on in the foreground and background. But I really love the blue sky and clouds!</td>', 'A little too much sun on your subject I think. Too much going on in the foreground and background. But I really love the blue sky and clouds!', '2007-09-06 13:23:12.000000', NULL, 1),
(4065317, 582235, 81664, '<td valign="top">What a delicate color. The pedals are so soft. Love the drops. Love the crisp focuses center. Nice background bokeh. I score you 8!</td>', 'What a delicate color. The pedals are so soft. Love the drops. Love the crisp focuses center. Nice background bokeh. I score you 8!', '2007-09-06 13:24:31.000000', NULL, 1);
