(4065407, 581733, 60698, '<td valign="top">I love this. It''s so creative and different! There is a wonderful contrast between the soft skin and the hard glass surface. The glowing light around the lips is lovely and the light orb in the background adds a nice touch! Nice detail in the glass marble!</td>', 'I love this. It''s so creative and different! There is a wonderful contrast between the soft skin and the hard glass surface. The glowing light around the lips is lovely and the light orb in the background adds a nice touch! Nice detail in the glass marble!', '2007-09-06 14:06:43.000000', NULL, 1),
(4065416, 581730, 60698, '<td valign="top">Perfect focus on the eye!! This is just beautiful in every way! You have all the primary colors and the way the body of the bird blends into the background and disappears makes this a true work of art! Almost abstract, but still recognizable. This image has a lot going for it and would make a lovely print.</td>', 'Perfect focus on the eye!! This is just beautiful in every way! You have all the primary colors and the way the body of the bird blends into the background and disappears makes this a true work of art! Almost abstract, but still recognizable. This image has a lot going for it and would make a lovely print.', '2007-09-06 14:10:43.000000', NULL, 1),
(4065479, 582570, 64929, '<td valign="top">My favorite butterfly outta the bunch!  Great Job!!!!!  *10*</td>', 'My favorite butterfly outta the bunch!  Great Job!!!!!  *10*', '2007-09-06 14:36:36.000000', NULL, 1),
(4065489, 581383, 61679, '<td valign="top">Back to comment and to bump: One of my favorites of the challenge. A little cropping on the left to get rid of the non-circular bokeh on the edge and this would have been perfect for my taste. 9</td>', 'Back to comment and to bump: One of my favorites of the challenge. A little cropping on the left to get rid of the non-circular bokeh on the edge and this would have been perfect for my taste. 9', '2007-09-06 14:38:36.000000', NULL, 1),
