(4076036, 582304, 39430, '<td valign="top">very crisp editing.  The uniformly sharp subject almost makes it look 2 dimensional.  You must have had good seperation from the background to be able to acheieve this.  :)  Maybe a closer crop would help the image to get rid of the extra leaves and clutter on the left.</td>', 'very crisp editing.  The uniformly sharp subject almost makes it look 2 dimensional.  You must have had good seperation from the background to be able to acheieve this.  :)  Maybe a closer crop would help the image to get rid of the extra leaves and clutter on the left.', '2007-09-09 23:12:51.000000', NULL, 1),
(4076040, 581861, 39430, '<td valign="top">White balance looks a little blue.  Pushing up the reds will help to warm it up.</td>', 'White balance looks a little blue.  Pushing up the reds will help to warm it up.', '2007-09-09 23:14:10.000000', NULL, 1),
(4076044, 582139, 39430, '<td valign="top">Oooh, very nice reflections, and a good composition offsetting the flowers.  My only complaint would be a little lack of focus on the flowers, but that''s minor.</td>', 'Oooh, very nice reflections, and a good composition offsetting the flowers.  My only complaint would be a little lack of focus on the flowers, but that''s minor.', '2007-09-09 23:15:12.000000', NULL, 1),
