(4080419, 581166, 39430, '<td valign="top">Hmm, very noisy, and no subject.</td>', 'Hmm, very noisy, and no subject.', '2007-09-11 08:20:00.000000', NULL, 1),
(4080420, 582126, 39430, '<td valign="top">Nice detail.  A little more open crop might help balance the foreground with the bokeh.</td>', 'Nice detail.  A little more open crop might help balance the foreground with the bokeh.', '2007-09-11 08:20:50.000000', NULL, 1),
(4080421, 580775, 39430, '<td valign="top">Nice buttery smooth background.</td>', 'Nice buttery smooth background.', '2007-09-11 08:21:51.000000', NULL, 1),
(4080428, 582495, 39430, '<td valign="top">Nicely balanced composition, but the high-contrast paint-brush filter hasn''t really worked well here.</td>', 'Nicely balanced composition, but the high-contrast paint-brush filter hasn''t really worked well here.', '2007-09-11 08:24:29.000000', NULL, 1),
(4080431, 582519, 39430, '<td valign="top">A bit soft on detail, and a bit low on contrast.  Push the contrast a little more, and sharpen it up, and you''ll have a nice rich-coloured image.</td>', 'A bit soft on detail, and a bit low on contrast.  Push the contrast a little more, and sharpen it up, and you''ll have a nice rich-coloured image.', '2007-09-11 08:26:01.000000', NULL, 1),
(4080433, 581602, 39430, '<td valign="top">The subject is hidden by the foreground, and also quite small in the photo.</td>', 'The subject is hidden by the foreground, and also quite small in the photo.', '2007-09-11 08:27:07.000000', NULL, 1),
(4080435, 582420, 39430, '<td valign="top">Nice colours and lines.  I''d like to see just a little more in focus, and less reds in the PP.</td>', 'Nice colours and lines.  I''d like to see just a little more in focus, and less reds in the PP.', '2007-09-11 08:28:04.000000', NULL, 1),
(4080439, 579314, 39430, '<td valign="top">Ooh, nice bug!  I''d recommend adjusting the WB a little to make it less blue/white, and more green.  Maybe a touch overexposed, losing some detail in the head?  Overall pretty good though.</td>', 'Ooh, nice bug!  I''d recommend adjusting the WB a little to make it less blue/white, and more green.  Maybe a touch overexposed, losing some detail in the head?  Overall pretty good though.', '2007-09-11 08:30:23.000000', NULL, 1),
(4080441, 580374, 39430, '<td valign="top">The black edge of the stands and the close crop makes the photo feel uncomfortably cramped, like he has to duck to fit in.  :)</td>', 'The black edge of the stands and the close crop makes the photo feel uncomfortably cramped, like he has to duck to fit in.  :)', '2007-09-11 08:31:47.000000', NULL, 1),
(4080442, 581432, 39430, '<td valign="top">I''d like to see the flower a little bigger in the frame.  Lovely background though!  Wow</td>', 'I''d like to see the flower a little bigger in the frame.  Lovely background though!  Wow', '2007-09-11 08:32:48.000000', NULL, 1),
(4080444, 579655, 39430, '<td valign="top">The subject needs more light - just move your hand 2 inches over into that patch of sun.</td>', 'The subject needs more light - just move your hand 2 inches over into that patch of sun.', '2007-09-11 08:33:51.000000', NULL, 1),
(4080446, 578937, 39430, '<td valign="top">Sorry, this is just no good at all, is it?</td>', 'Sorry, this is just no good at all, is it?', '2007-09-11 08:34:34.000000', NULL, 1),
(4080450, 582075, 39430, '<td valign="top">Would be nice to see just a little more light on this side of his face.  Nice rim lighting, but he needs a main-light to make him more visible as the subject.</td>', 'Would be nice to see just a little more light on this side of his face.  Nice rim lighting, but he needs a main-light to make him more visible as the subject.', '2007-09-11 08:35:51.000000', NULL, 1),
(4080454, 581732, 39430, '<td valign="top">Not quite in crisp focus, but nice bokeh and nice warm colours.</td>', 'Not quite in crisp focus, but nice bokeh and nice warm colours.', '2007-09-11 08:36:48.000000', NULL, 1),
(4080458, 582237, 39430, '<td valign="top">The gem is not quite in focus.  Other than that, not bad.</td>', 'The gem is not quite in focus.  Other than that, not bad.', '2007-09-11 08:37:51.000000', NULL, 1),
