(4086715, 581294, 49643, '<td valign="top">Beautiful background!! It almost gives feel like oil painting!</td>', 'Beautiful background!! It almost gives feel like oil painting!', '2007-09-13 05:29:16.000000', NULL, 0),
(4086727, 581699, 61336, '<td valign="top">Amazing shot in every way. Congrats on the blue.</td>', 'Amazing shot in every way. Congrats on the blue.', '2007-09-13 05:48:46.000000', NULL, 0),
(4086871, 581199, 61971, '<td valign="top">you should really send this one to apple! Great job</td>', 'you should really send this one to apple! Great job', '2007-09-13 08:39:47.000000', NULL, 0),
(4086874, 581134, 61971, '<td valign="top">beautiful lighting on the rose. love this picture.</td>', 'beautiful lighting on the rose. love this picture.', '2007-09-13 08:42:42.000000', NULL, 0),
(4086876, 581138, 61971, '<td valign="top">i agree with the you got robbed statement. Awesome shot</td>', 'i agree with the you got robbed statement. Awesome shot', '2007-09-13 08:44:01.000000', NULL, 0),
(4086933, 581433, 20941, '<td valign="top">Congratulations on the first Ribbon! Beautiful entry!!</td>', 'Congratulations on the first Ribbon! Beautiful entry!!', '2007-09-13 09:27:29.000000', NULL, 0),
(4087096, 579650, 32767, '<td valign="top">I like the border. It''s complex yet subtle. The bokeh is nicely rendered. While the flower looks very nice it seems to be dwarfed by the vast green. The total image has a great feel, nice work.</td>', 'I like the border. It''s complex yet subtle. The bokeh is nicely rendered. While the flower looks very nice it seems to be dwarfed by the vast green. The total image has a great feel, nice work.', '2007-09-13 10:47:19.000000', NULL, 0),
(4087188, 581733, 60805, '<td valign="top">definitely ribbon quality. Oh well :)</td>', 'definitely ribbon quality. Oh well :)', '2007-09-13 11:22:10.000000', NULL, 0),
(4087201, 581699, 24454, '<td valign="top">How beautiful!  What talent and wonderful opportunity to make a spider web look so magical!  Congratulations on top honors for this beautiful photo!<br/> <br/></td>', 'How beautiful!  What talent and wonderful opportunity to make a spider web look so magical!  Congratulations on top honors for this beautiful photo! ', '2007-09-13 11:26:26.000000', NULL, 0),
(4087203, 581433, 24454, '<td valign="top">Hey, congratulations on your first ribbon for this amazing photo!  You''re right. . .I''m sure it is the first of many for you. You have some really awesome photos!<br/> <br/></td>', 'Hey, congratulations on your first ribbon for this amazing photo!  You''re right. . .I''m sure it is the first of many for you. You have some really awesome photos! ', '2007-09-13 11:27:44.000000', NULL, 0),
(4087207, 581877, 24454, '<td valign="top">Awwwwwesome!!!  Congratulations on this BEAUTIFUL photo!  Oh. . and the ribbon too :)<br/> <br/></td>', 'Awwwwwesome!!!  Congratulations on this BEAUTIFUL photo!  Oh. . and the ribbon too :) ', '2007-09-13 11:28:23.000000', NULL, 0),
(4087216, 580787, 24454, '<td valign="top">Ohmygoodness. . .what a BEAUTIFUL <b>BEAUTIFUL</b> photo.   Darn!  We need 4 ribbons this time!  WOW!<br/> <br/></td>', 'Ohmygoodness. . .what a BEAUTIFUL BEAUTIFUL photo.   Darn!  We need 4 ribbons this time!  WOW! ', '2007-09-13 11:30:50.000000', NULL, 0),
(4087220, 582098, 24454, '<td valign="top">Oh Jason!  This TOTALLY rocks!!  You are amazing!  CONGRATULATIONS on more top honors with your excellent photography!   What a gift to take ordinary objects and turn them into a truly WOW photo!<br/> <br/></td>', 'Oh Jason!  This TOTALLY rocks!!  You are amazing!  CONGRATULATIONS on more top honors with your excellent photography!   What a gift to take ordinary objects and turn them into a truly WOW photo! ', '2007-09-13 11:33:01.000000', NULL, 0),
(4087223, 580422, 24454, '<td valign="top">Wow!  This is AWESOME!  Truly magical and 3-dimensional!  Yes, very much ribbon quality!  CONGRATULATIONS!<br/> <br/></td>', 'Wow!  This is AWESOME!  Truly magical and 3-dimensional!  Yes, very much ribbon quality!  CONGRATULATIONS! ', '2007-09-13 11:34:18.000000', NULL, 0),
(4087226, 581733, 24454, '<td valign="top">I think its perfect -- and I can''t imagine a better choice!  Congratulations.  This is so interesting and striking!<br/> <br/></td>', 'I think its perfect -- and I can''t imagine a better choice!  Congratulations.  This is so interesting and striking! ', '2007-09-13 11:35:58.000000', NULL, 0),
